import {ITEMS,RECIPES,fresh,parseSave,has,canAfford,harvest,start,tick,orders,order,selectOrder,dispatch,build,buildCost,upgrade,upgradeWorkshops,milestone,canCancel,cancel,prioritize,capacity,setTarget,PIER_COST,WORKSHOP_COST,underConstruction,CONSTRUCTION_SECONDS,unlocked,PATHS,CONTRACTS,CHARTER_COST,pathBlocker,specialise,invest,availableContracts,acceptContract,contractReady,dispatchContract,abandonContract,establishCharter,chapterTwo,maxBatches,queueBatch,harvestReplant,incoming,openingGuide,REFITS,recipeDuration,refitBlocker,installRefit} from './engine.js';
import {createHarbourScene} from './scene.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const KEY='little-harbour-v1';let state=fresh(),storageOK=true,saveWarning='';
try{const saved=localStorage.getItem(KEY);if(saved){try{state=parseSave(saved);}catch{saveWarning='The previous save could not be loaded. A new town has been opened.';}}}catch{storageOK=false;}
let tab='produce',station='overview',toastTimer,pendingImport=null,scene,mapFitted=false,labelsVisible=true,milestoneTimer,seenMilestones=new Set();
const glyph={wheat:'♧',flour:'◈',bread:'◒',olives:'❧',oil:'♙',fish:'≋',wood:'▱',stone:'◇',planks:'▱',boatparts:'⚒',grapes:'❦',wine:'♙'};
const stationNames={field:'Field',mill:'Mill',bakery:'Bakery',fishing:'Fishing',olive:'Olives',boatyard:'Boatyard',estate:'Cellar'};
const goals=[
 ['Start with the wheat field','Harvest six wheat. Your first field is already ripe.'],
 ['Turn wheat into flour','Select the stone mill. Two wheat make two flour.'],
 ['Fire up the bakery','Use two flour to bake two loaves. The mill can work alongside it.'],
 ['Make your first delivery','Supply four bread to Cala Verde. Keep the mill and bakery working.'],
 ['Choose your next livelihood','Your first delivery funds a fishing jetty or an olive workshop.'],
 ['Extend the working quay','Trade your new goods. Save 140 coins, 10 timber and 8 stone to extend the quay.'],
 ['A working harbour','Chapter complete. Choose trade routes, set stock targets, and build your second business.']
];
function esc(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#saveStatus').textContent=storageOK?'Saved on this device':'Use Export to keep your town';$('#autosaveWarning').hidden=storageOK;}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300);}
function costs(c){return Object.entries(c).map(([k,v])=>`${v} ${k==='coins'?'coins':ITEMS[k].toLowerCase()}`).join(' · ');}
function ingredients(c){return Object.entries(c).map(([k,v])=>{const ready=state.stock[k]>=v,queued=incoming(state,k);return `<div class="ingredient-row"><div><span>${ITEMS[k]}</span>${queued?`<small>${queued} in production</small>`:''}</div><div class="ingredient-amount"><strong class="${ready?'enough':''}">${state.stock[k]} / ${v} needed</strong>${!ready?`<button class="text-button" data-action="ingredient" data-key="${k}">${queued>=v-state.stock[k]?'View queue':'Make '+(v-state.stock[k]-queued)} →</button>`:''}</div></div>`;}).join('');}
function recipeButton(key,text){const r=RECIPES[key],max=maxBatches(state,key),lacks=!canAfford(state,r.cost);return `<div class="batch-controls"><button class="button" data-action="start" data-key="${key}" ${max?'':'disabled'}>${max?text:state.jobs.filter(j=>RECIPES[j.key].station===r.station).length>=capacity(state,r.station)?'Queue full':text}</button>${key!=='field'?`<button class="button secondary batch-fill" data-action="batch" data-key="${key}" data-count="${max}" ${max>1?'':'disabled'} aria-label="Queue ${max} batches: ${r.name}">×${Math.max(1,max)}<small>Fill queue</small></button>`:''}</div>${lacks?`<p class="hint">Needs ${costs(r.cost)}. <button class="text-button" data-action="ingredient" data-key="${Object.keys(r.cost)[0]}">Go to source →</button></p>`:''}`;}
function activeStations(){return ['field','mill','bakery',...state.businesses,...state.specialists.filter(k=>state.charter||PATHS[state.specialisation]?.station===k)];}
function quickActions(){const o=order(state),ready=!o.locked&&canAfford(state,o.cost),growing=state.jobs.some(j=>j.key==='field');return `<div class="quick-heading"><span class="section-label">AT A GLANCE</span><button class="text-button" data-station="overview">All workshops →</button></div><div class="quick-actions"><button data-action="${state.ripe?'harvest-replant':'start'}" data-key="field" ${growing?'disabled':''}><strong>${state.ripe?'Harvest & replant':growing?'Wheat growing':'Plant wheat'}</strong><small>${state.ripe?'+6 wheat · next crop started':growing?'Use Production to check progress':'Start the next crop'}</small></button><button data-action="${ready?'dispatch':'open-trade'}"><strong>${ready?'Dispatch to '+o.name:'Prepare a delivery'}</strong><small>${ready?'+'+o.coins+' coins · materials included':o.locked?'Build your first business':'See goods needed for '+o.name}</small></button>${state.contract?`<button data-action="${contractReady(state)?'contract-dispatch':'go-contracts'}"><strong>${contractReady(state)?'Dispatch contract shipment':'View current contract'}</strong><small>Shipment ${state.contract.shipped+1} / 3</small></button>`:''}</div>`;}
function stationArt(st){return `<div class="station-art art-${st}" aria-hidden="true"></div>`;}
function productionOverview(){return `<h2>Keep the town moving.</h2><p class="description">See every workshop, start a batch, or open its queues and stock targets.</p><div class="workshop-overview">${activeStations().map(st=>{const project=underConstruction(state,st),jobs=state.jobs.filter(j=>RECIPES[j.key].station===st),keys=Object.keys(RECIPES).filter(k=>RECIPES[k].station===st),status=project?'Under construction':st==='field'&&state.ripe?'Ready to harvest':jobs.length?jobs.length+' / '+capacity(state,st)+' slots in use':'Idle';return `<article class="workshop-card">${stationArt(st)}<div class="workshop-heading"><button class="text-button" data-station="${st}">${stationNames[st]} →</button><span class="${!jobs.length&&!project?'idle-label':''}">${status}</span></div>${jobs.length?`<p class="workshop-timing" data-stationtime="${st}"></p>`:''}${project?`<p class="hint">Your crew is on site.</p>`:keys.map(k=>{const r=RECIPES[k],item=Object.keys(r.output)[0],harvesting=k==='field'&&state.ripe;return `<div class="workshop-recipe"><div><strong>${ITEMS[item]} <b>${state.stock[item]}</b></strong><small>${incoming(state,item)?incoming(state,item)+' in production':Object.keys(r.cost).length?costs(r.cost):'No ingredients needed'}</small></div><button data-action="${harvesting?'harvest-replant':'start'}" data-key="${k}" ${harvesting||maxBatches(state,k)?'':'disabled'}>${harvesting?'Harvest + plant':'Make '+r.output[item]}</button></div>`;}).join('')}</article>`;}).join('')}</div>`;}
function autoControl(key){if(!state.pier)return '';const value=state.targets[key]||0,item=Object.keys(RECIPES[key].output)[0];return `<div class="auto-control"><div><strong>${key==='field'?'Farmhand':key==='press'?'Oil target':key==='olives'?'Olive target':'Stock target'}</strong><small>${value?'Maintain '+value+' '+ITEMS[item].toLowerCase():'Manual production'}</small></div><div class="segmented" aria-label="${RECIPES[key].name} stock target">${[0,6,12].map(v=>`<button data-action="target" data-key="${key}" data-value="${v}" aria-pressed="${value===v}" class="${value===v?'active':''}">${v||'Off'}</button>`).join('')}</div></div>`;}
function jobList(){return `<div class="queue"><div class="section-label">PRODUCTION QUEUE <span>${capacity(state,station)} SLOTS HERE</span></div>${state.jobs.length?state.jobs.map((j,i)=>`<div class="job"><div class="job-name"><span>${RECIPES[j.key].name}</span><small data-jobtime="${i}"></small></div><div class="progress"><i data-jobbar="${i}"></i></div>${canCancel(state,i)?`<div class="job-actions"><button data-action="prioritize" data-index="${i}">Move next</button><button data-action="cancel" data-index="${i}">Cancel & refund</button></div>`:''}</div>`).join(''):'<div class="empty-queue">No work in progress. Start a batch to keep the harbour moving.</div>'}</div>`;}
function recipeCard(input,output,left,right,duration){return `<div class="recipe-card"><div class="chain"><div class="object"><b>${glyph[input]||input}</b><small>${left}</small></div><span class="arrow">→</span><div class="object"><b>${glyph[output]||output}</b><small>${right}</small></div></div><div class="recipe-meta"><span>Local production</span><span>${duration} simulation seconds</span></div></div>`;}
function production(){
 const available=['overview',...activeStations()];
 let html=`<div class="station-selector">${available.map(k=>`<button data-station="${k}" aria-pressed="${station===k}" class="${station===k?'active':''}">${k==='overview'?'Overview':stationNames[k]}</button>`).join('')}</div><div class="panel-eyebrow">LOCAL PRODUCTION</div>`;
 if(station==='overview')return html+productionOverview();
 html+=stationArt(station);
 const project=underConstruction(state,station);
 if(project)return html+`<h2>${({fishing:'Fishing jetty',olive:'Olive workshop',boatyard:'Boatyard',estate:'Vineyard & cellar'})[station]}</h2><div class="construction-card"><span class="panel-eyebrow">CREW ON SITE</span><h3>Taking shape.</h3><p>Materials are paid for. Your crew is building the ${({fishing:'jetty',olive:'olive workshop',boatyard:'boatyard',estate:'vineyard and cellar'})[station]}.</p><div class="progress"><i data-buildbar="${station}"></i></div><div class="construction-meta"><span data-buildtime="${station}"></span><span>Simulation time</span></div></div><p class="hint">Watch the site on the map, or keep your mill and bakery working. Construction follows the pause and speed controls.</p><button class="button secondary" data-action="watch-build" data-key="${station}">Watch construction</button>`+jobList();
 if(station==='field')html+=`<h2>Wheat field</h2><p class="description">Harvest and replant. A steady supply of wheat keeps your mill working.</p>${recipeCard('wheat','wheat','One field','6 wheat',12)}${state.ripe?'<button class="button" data-action="harvest-replant">Harvest 6 wheat & replant</button>':recipeButton('field','Plant wheat')}${autoControl('field')}<p class="hint">Crops stay ready until collected. Nothing spoils while you’re away.</p>`;
 else if(station==='fishing')html+=`<h2>Fishing jetty</h2><p class="description">Send your boat out for fresh fish. Every trip brings back two crates.</p>${recipeCard('⚓','fish','Fishing boat','2 fish',recipeDuration(state,'fishing'))}${recipeButton('fishing','Send boat · catch 2 fish')}${autoControl('fishing')}`;
 else if(station==='olive')html+=`<h2>Olive workshop</h2><p class="description">Harvest the grove, then press your olives into oil. Both jobs share this workshop’s queue.</p>${recipeCard('olives','oil','2 olives','2 olive oil',12)}${recipeButton('olives','Harvest 4 olives')}${ingredients({olives:2})}${recipeButton('press','Press 2 olive oil')}${autoControl('olives')}${autoControl('press')}`;
 else if(station==='boatyard')html+=`<h2>Boatyard</h2><p class="description">Timber becomes planks, then fittings for the coastal fleet. Both jobs share this workshop.</p>${recipeCard('wood','planks','2 timber','4 planks',12)}${ingredients({wood:2})}${recipeButton('saw','Saw 4 planks')}${ingredients({planks:4})}${recipeButton('fittings','Make 2 boat fittings')}${autoControl('saw')}${autoControl('fittings')}<p class="hint">Fittings use construction timber. Keep a Porto Santo materials route working alongside your contract.</p>`;
 else if(station==='estate')html+=`<h2>Vineyard & cellar</h2><p class="description">Harvest grapes and turn them into wine. The cellar and harvest crew share this queue.</p>${recipeCard('grapes','wine','4 grapes','2 wine',24)}${recipeButton('grapes','Harvest 4 grapes')}${ingredients({grapes:4})}${recipeButton('wine','Make 2 wine')}${autoControl('grapes')}${autoControl('wine')}<p class="hint">Each wine batch takes 24 simulation seconds. Keep harvesting ahead of the cellar.</p>`;
 else {const mill=station==='mill',input=mill?'wheat':'flour',output=mill?'flour':'bread',r=RECIPES[station];html+=`<h2>${mill?'Stone mill':'Bakery'}</h2><p class="description">${mill?'Turn the harvest into flour. Keep a batch ready for the bakery.':'Bake bread for the village and the boats that trade along the coast.'}</p>${recipeCard(input,output,'2 '+ITEMS[input].toLowerCase(),'2 '+ITEMS[output].toLowerCase(),recipeDuration(state,station))}${ingredients(r.cost)}${recipeButton(station,mill?'Mill 2 flour':'Bake 2 bread')}${autoControl(station)}<p class="hint">Finished goods move straight into storage. Buildings work in parallel.</p>`;}
 return html+(REFITS[station]?refitSummary(station):'')+(state.speed===0?'<div class="paused-note">Simulation paused. Select 1× or 3× to resume.</div>':'')+jobList();
}
function tradePanel(){const o=order(state),routes=orders(state);return `<div class="panel-eyebrow">COASTAL TRADE</div><h2>The harbour</h2><p class="description">Choose what to ship and what your town needs in return.</p>${routes.length>1?`<div class="route-options">${routes.map(r=>`<button data-action="route" data-key="${r.id}" class="${r.id===o.id?'active':''}" aria-pressed="${r.id===o.id}"><span>${r.name}</span><small>${r.id==='materials'?'Building materials':r.id==='specialist'?'Specialist cargo':'Market supplies'}</small></button>`).join('')}</div>`:''}<div class="order-destination"><span>⚓</span><div><strong>${o.name}</strong><small>${state.pier?'Extended quay':'Local supply route'}</small></div></div><p class="description">${o.description}</p>${o.locked?'<button class="button" data-action="go-build">Choose an expansion</button>':`${ingredients(o.cost)}<div class="reward"><span>Earnings</span><strong>${o.coins} coins</strong></div><div class="reward"><span>Materials</span><strong>${o.wood} timber · ${o.stone} stone</strong></div><button class="button" data-action="dispatch" ${canAfford(state,o.cost)?'':'disabled'}>Load & dispatch</button><p class="hint">${canAfford(state,o.cost)?'All goods are ready. Earnings arrive immediately on dispatch.':'Produce the missing goods. There are no delivery deadlines.'}</p>${!canAfford(state,o.cost)?'<button class="button secondary" data-action="missing">Find missing goods</button>':''}`}<div class="ingredient-row"><span>Completed deliveries</span><strong>${state.deliveries}</strong></div><div class="queue"><div class="section-label">STOREHOUSE</div><div class="full-inventory">${Object.entries(ITEMS).map(([k,n])=>`<span>${n}<b>${state.stock[k]}</b></span>`).join('')}</div></div>`;}
function growthPanel(){
 const active=PATHS[state.specialisation];
 let html=`<section class="growth-section"><div class="panel-eyebrow">CHAPTER 02 · TOWN DIRECTION</div><h2>A town of your own.</h2><p class="description">${state.charter?'Your charter permits both specialist plots to operate. Choose which contracts to pursue next.':'One active specialist plot. Choose where to invest; existing buildings and goods stay yours if you change direction.'}</p>`;
 html+=`<div class="path-options">${Object.entries(PATHS).map(([id,p])=>{const selected=state.specialisation===id,blocker=pathBlocker(state,id);return `<article class="path-card ${selected?'selected':''}"><div class="path-heading"><h3>${p.name}</h3>${selected?'<span class="selected-label">SELECTED</span>':''}</div><p>${p.description}</p><div class="supply-chain">${p.chain}</div><button class="button ${selected?'secondary':''}" data-action="specialise" data-key="${id}" ${selected||blocker?'disabled':''}>${selected?'Current town direction':'Choose '+p.name.toLowerCase()}</button>${blocker&&!selected?`<p class="hint">${blocker}</p>`:''}</article>`;}).join('')}</div>`;
 if(active){const owned=state.specialists.includes(active.station),project=underConstruction(state,active.station),baseReady=has(state,active.requires)&&!underConstruction(state,active.requires);html+=`<article class="build-card specialist-investment"><h3>${active.building}</h3><p>${active.chain}. ${owned?'Your investment remains yours when you switch direction.':'Your specialist plot opens new products and multi-shipment contracts.'}</p>${owned?project?`<div class="construction-meta">Crew on site · <span data-buildtime="${active.station}"></span></div><button class="text-button" data-action="watch-build" data-key="${active.station}">Watch construction →</button>`:`<button class="text-button" data-station="${active.station}">Manage production →</button><button class="button secondary" data-action="go-contracts">View contracts</button>`:`<div class="cost">${costs(active.cost)}</div><button class="button" data-action="invest" ${baseReady&&canAfford(state,active.cost)?'':'disabled'}>Build ${active.building.toLowerCase()}</button><p class="hint">${!baseReady?'First build and finish the '+(active.requires==='fishing'?'fishing jetty':'olive workshop')+' below.':!canAfford(state,active.cost)?'Keep normal trade running to fund this investment.':'Investment is ready.'}</p>`}</article>`;}
 html+=`<article class="build-card charter-card"><div class="panel-eyebrow">LONGER-TERM PROJECT</div><h3>Harbour charter</h3><p>Earn two different trade partnerships, then establish the charter. Both specialist plots can operate together and normal trade earns 20% more.</p><div class="partnership-progress"><span>${state.contractsDone.length} / 2 partnerships</span><div class="progress"><i style="width:${Math.min(state.contractsDone.length/2,1)*100}%"></i></div></div>${state.charter?'<span class="success-tag">Charter earned · Chapter complete</span>':`<div class="cost">${costs(CHARTER_COST)}</div><button class="button" data-action="charter" ${state.contractsDone.length>=2&&canAfford(state,CHARTER_COST)?'':'disabled'}>Establish harbour charter</button>`}</article></section><div class="section-label basic-development-label">LOCAL BUILDINGS & INFRASTRUCTURE</div>`;
 return html;
}
function contractsPanel(){
 if(!state.specialisation)return '<div class="panel-eyebrow">LASTING PARTNERSHIPS</div><h2>More than one shipment.</h2><p class="description">Choose a town direction and invest in its specialist building. Contracts will connect your production decisions to a longer-term goal.</p><button class="button" data-action="go-build">Choose town direction</button>';
 const p=PATHS[state.specialisation],ready=state.specialists.includes(p.station)&&!underConstruction(state,p.station);
 let html=`<div class="panel-eyebrow">${p.name.toUpperCase()} · CONTRACTS</div><h2>Lasting partnerships.</h2><p class="description">One contract at a time. Three shipments make a partnership. Normal trade stays available for coins and materials.</p>`;
 if(state.contract){const c=CONTRACTS[state.contract.id],shipped=state.contract.shipped;html+=`<article class="contract-card"><span class="panel-eyebrow">${c.client}</span><h3>${c.name}</h3><p>${c.description}</p><div class="contract-progress">${Array.from({length:c.shipments},(_,i)=>`<span class="${i<shipped?'done':''}">${i<shipped?'✓':i+1}</span>`).join('')}<strong>${shipped} / ${c.shipments} delivered</strong></div><div class="section-label">SHIPMENT ${shipped+1} · GOODS REQUIRED</div>${ingredients(c.cost)}<div class="reward"><span>Each shipment</span><strong>${c.coins} coins · ${c.wood} timber · ${c.stone} stone</strong></div><div class="reward"><span>Completion bonus</span><strong>${c.bonus} coins + partnership</strong></div><button class="button" data-action="contract-dispatch" ${contractReady(state)?'':'disabled'}>Dispatch shipment ${shipped+1}</button>${!contractReady(state)?'<button class="button secondary" data-action="contract-missing">Find missing goods</button>':''}<p class="hint">No deadline. You keep each shipment’s earnings. Already delivered goods are committed to this contract.</p><button class="text-button release-contract" data-action="leave-contract">Release contract</button></article>`;}
 else html+=availableContracts(state).map(c=>`<article class="contract-card"><span class="panel-eyebrow">${c.client}</span><h3>${c.name}</h3><p>${c.description}</p><div class="contract-requirements"><span>Per shipment</span><strong>${costs(c.cost)}</strong></div><div class="contract-requirements"><span>Commitment</span><strong>${c.shipments} shipments</strong></div><div class="contract-requirements"><span>Total earnings</span><strong>${c.coins*c.shipments+c.bonus} coins + materials</strong></div>${state.contractsDone.includes(c.id)?'<span class="success-tag">Partnership established · replay available</span>':'<p class="hint">Completing this contract earns a new partnership toward your charter.</p>'}<button class="button" data-action="accept-contract" data-key="${c.id}" ${ready?'':'disabled'}>Accept ${c.name.toLowerCase()}</button>${!ready?'<p class="hint">Build and finish your '+p.building.toLowerCase()+' first.</p>':''}</article>`).join('');
 html+=`<div class="partnership-summary"><strong>${state.contractsDone.length} / 2 distinct partnerships</strong><p>Two different contracts qualify your town for the harbour charter. Replays earn coins, but not another partnership.</p></div>`;
 return html;
}

function refitSummary(st){const mode=state.refits[st];return `<div class="refit-summary"><strong>${mode?REFITS[st][mode].name:'Workshop setup'}</strong><p>${mode==='speed'?'Batches take 25% less time.':mode==='queue'?'Two additional queue slots.':'Choose faster batches or longer production queues after your first business.'}</p><button class="text-button" data-action="refit-options" data-key="${st}">${mode?'Review setup':'Compare improvements'} →</button></div>`;}
function refitCard(st){const p=REFITS[st],current=state.refits[st];return `<article class="refit-card"><h3>${p.name}</h3><div class="refit-choices">${['speed','queue'].map(mode=>{const choice=p[mode],blocker=refitBlocker(state,st,mode),installed=current===mode,base=RECIPES[st].duration;return `<section class="refit-choice ${installed?'installed':''}"><span class="panel-eyebrow">${mode==='speed'?'FASTER BATCHES':'LONGER QUEUES'}</span><h4>${choice.name}</h4><p>${mode==='speed'?base+'s → '+base*.75+'s per batch. Same ingredients and output.':'+2 queue slots: '+((state.workshopUpgrade?4:2)+2)+' total. Batches keep their normal duration.'}</p><div class="cost">${costs(choice.cost)}</div><button class="button ${installed?'secondary':''}" data-action="refit" data-key="${st}" data-mode="${mode}" ${blocker?'disabled':''}>${installed?'Installed':current?'Replace current setup':'Install improvement'}</button>${blocker&&!installed?`<p class="hint">${blocker}</p>`:''}</section>`;}).join('')}</div>${state.jobs.some(j=>RECIPES[j.key].station===st)?`<button class="text-button" data-station="${st}">Manage queues & stock targets →</button>`:''}</article>`;}
function refitsPanel(){return `<section class="refits-section"><div class="panel-eyebrow">INVEST IN YOUR EXISTING TOWN</div><h2>Improve or expand?</h2><p class="description">Choose one setup per workshop. Faster batches suit active play; extra queue space lets you plan longer runs. These use the same funds as new buildings.</p><p class="hint">Refits require an idle workshop. Switch off its stock target if needed. Replacing a setup costs the new refit price; the old setup is not refunded.</p>${Object.keys(REFITS).map(refitCard).join('')}</section>`;}
function buildPanel(){
 let html='<div class="panel-eyebrow">TOWN DEVELOPMENT</div><h2>Room to grow.</h2><p class="description">New businesses create new goods. Better infrastructure gives you more ways to manage them.</p>';
 for(const type of ['fishing','olive']){const owned=has(state,type),project=underConstruction(state,type),unlocked=state.deliveries>0&&(!state.expansion||state.pier),cost=buildCost(state);html+=`<article class="build-card"><h3>${type==='fishing'?'Fishing jetty':'Olive workshop'}</h3><p>${type==='fishing'?'A direct supply chain: boat → fish → coastal market.':'A two-step supply chain: olives → oil → coastal market.'}</p>${owned&&project?`<p class="construction-meta">Crew on site · <span data-buildtime="${type}"></span></p><button class="text-button" data-action="watch-build" data-key="${type}">Watch construction →</button>`:owned?`<button class="text-button" data-station="${type}">Operating · Manage production →</button>`:`<div class="cost">${costs(cost)}</div><button class="button" data-action="build" data-key="${type}" ${unlocked&&canAfford(state,cost)?'':'disabled'}>Build ${type==='fishing'?'fishing jetty':'olive workshop'}</button><p class="hint">${!state.deliveries?'Complete your first bread delivery.':state.expansion&&!state.pier?'Extend the quay to unlock your second business.':!canAfford(state,cost)?'Trade for the remaining funds and materials.':'Ready to build.'}</p>`}</article>`;}
 html+=`<article class="build-card"><h3>Extend the quay</h3><p>Choose between three trade routes. Unlock stock targets and your second business.</p>${state.pier?(underConstruction(state,'pier')?'<span class="success-tag">Crew extending the quay</span>':'<span class="success-tag">Quay extension complete</span>'):`<div class="cost">${costs(PIER_COST)}</div><button class="button" data-action="upgrade" ${state.deliveries>=2&&state.expansion&&canAfford(state,PIER_COST)?'':'disabled'}>Extend quay</button><p class="hint">${state.deliveries<2?'Complete a shipment from your first business.':!canAfford(state,PIER_COST)?'Complete another delivery for the remaining resources.':'Materials and funds are ready.'}</p>`}</article>`;
 html+=`<article class="build-card"><h3>Organise the storehouse</h3><p>Four queue slots at every workshop. Plan longer production runs.</p>${state.workshopUpgrade?(underConstruction(state,'storehouse')?'<span class="success-tag">Crew organising the storehouse</span>':'<span class="success-tag">Four queue slots available</span>'):`<div class="cost">${costs(WORKSHOP_COST)}</div><button class="button" data-action="workshops" ${state.pier&&canAfford(state,WORKSHOP_COST)?'':'disabled'}>Improve workshops</button>${!state.pier?'<p class="hint">Requires the extended quay.</p>':''}`}</article>`;
 return (state.pier?growthPanel():'')+html+refitsPanel();
}
function earnedMilestones(){return [state.deliveries>0?'delivery':null,...state.businesses.filter(k=>!underConstruction(state,k)),state.pier&&!underConstruction(state,'pier')?'pier':null].filter(Boolean);}
function resetMilestones(){seenMilestones=new Set(earnedMilestones());clearTimeout(milestoneTimer);$('#milestoneNotice').hidden=true;}
function checkMilestones(){const fresh=earnedMilestones().filter(k=>!seenMilestones.has(k));fresh.forEach(k=>seenMilestones.add(k));if(!fresh.length)return;$('#toast').classList.remove('visible');clearTimeout(toastTimer);const key=fresh.at(-1),copy={delivery:['The first boat has traded.','Your bread earned 80 coins, 8 timber and 4 stone. Choose fishing or olive oil for your next business.'],fishing:['The fishing jetty is open.','Send your first boat out. Fish and bread will supply the next coastal route.'],olive:['The olive workshop is open.','Gather olives, then press oil. Keep the bakery working alongside your new business.'],pier:['A wider coast is open.','Three trade routes, stock targets and a second business are now within reach.']}[key];$('#milestoneTitle').textContent=copy[0];$('#milestoneDescription').textContent=copy[1];$('#milestoneNotice').hidden=false;clearTimeout(milestoneTimer);milestoneTimer=setTimeout(()=>$('#milestoneNotice').hidden=true,11000);scene?.emit('milestone',key);}
function updateGuide(){const g=openingGuide(state);$('#goalTitle').textContent=g.title;$('#goalDescription').textContent=g.description;$('#goalAction').textContent=g.label;const o=order(state);$('#openingCargo').innerHTML=!state.pier&&!o.locked?Object.entries(o.cost).map(([k,n])=>`<span class="${state.stock[k]>=n?'complete':''}">${ITEMS[k]} <b>${Math.min(state.stock[k],n)} / ${n}</b>${incoming(state,k)?`<small>+${incoming(state,k)} in production</small>`:''}</span>`).join(''):'';}
function runGuide(){const g=openingGuide(state);if(g.action==='view'){if(g.tab==='resume'){state.speed=1;render();return;}if(g.tab==='map'){focusMap(g.station);return;}choose(g.tab,g.station,true);return;}handleClick({target:{closest:()=>({dataset:{action:g.action,key:g.key,count:String(g.count||1)},disabled:false})}});}
function focusMap(key){const pin=$(key==='pier'?'.harbour-pin':key==='olive'?'.expansion-pin':key==='fishing'?'.fishing-pin':['boatyard','estate'].includes(key)?'#specialistPin':key==='mill'?'.mill-pin':key==='bakery'?'.bakery-pin':'.field-pin');$('#map').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});if(pin&&!mapFitted)$('.map-scroller').scrollTo({left:Math.max(0,pin.offsetLeft-$('.map-scroller').clientWidth/2),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function render(){
 const focus=document.activeElement,focusKey=focus?.dataset?.focusKey;
 $('#coins').textContent=state.coins;
 $('#townSubtitle').textContent=state.pier?'An established harbour. New routes ahead.':state.expansion?'Your first business is taking root.':state.deliveries?'The first trade is done. Time to grow.':'A small harbour. Your first working day.';
 $('#cargoSupplies').hidden=!state.deliveries;
 $('#map').classList.toggle('map-fitted',mapFitted);
 $('#map').classList.toggle('quiet-labels',!labelsVisible);
 $('#mapView').textContent=mapFitted?'Explore close up':'Whole harbour';$('#mapView').setAttribute('aria-pressed',String(mapFitted));
 $('#labelToggle').textContent=labelsVisible?'Labels on':'Labels off';$('#labelToggle').setAttribute('aria-pressed',String(labelsVisible));
 $('#quickActions').innerHTML=quickActions();
 $('#mobileContracts').hidden=!state.pier;
 const visible=['wheat','flour','bread','wood','stone',...(has(state,'fishing')?['fish']:[]),...(has(state,'olive')?['oil']:[]),...(state.specialists.includes('boatyard')?['planks','boatparts']:[]),...(state.specialists.includes('estate')?['grapes','wine']:[])];
 $('#resources').innerHTML=visible.map(k=>`<button class="resource" data-action="ingredient" data-key="${k}" aria-label="Open ${ITEMS[k]} production" title="${ITEMS[k]}"><span class="resource-icon" aria-hidden="true">${glyph[k]}</span><em>${ITEMS[k]}</em><strong>${state.stock[k]}</strong></button>`).join('');
 $$('.tabs [data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-pressed',String(b.dataset.tab===tab));});
 $$('.map-pin').forEach(b=>b.classList.toggle('selected',b.dataset.select===(tab==='trade'?'trade':tab==='build'?'build':station)));
 $('#panel').innerHTML=tab==='produce'?production():tab==='trade'?tradePanel():tab==='contracts'?contractsPanel():buildPanel();
 $$('#panel button, #quickActions button, #resources button').forEach((b,i)=>b.dataset.focusKey=[tab,station,b.dataset.action,b.dataset.key,b.dataset.station,b.dataset.index,b.dataset.value,i].join('|'));
 if(focusKey){const restored=$$('#panel button, #quickActions button, #resources button').find(b=>b.dataset.focusKey===focusKey);if(restored&&!restored.disabled)restored.focus({preventScroll:true});}
 $('#log').innerHTML=state.log.map(t=>`<li>${esc(t)}</li>`).join('');
 const m=milestone(state),growth=state.pier?chapterTwo(state):null,step=growth?growth.step:m;$('#chapterLabel').textContent=growth?'CHAPTER 02 · A TOWN OF YOUR OWN':'CHAPTER 01 · A WORKING HARBOUR';$('#goalTitle').textContent=growth?growth.title:goals[m][0];$('#goalDescription').textContent=growth?growth.description:goals[m][1];$('#chapterCount').textContent=step+' / 6';$('#journeyTrack').innerHTML=Array.from({length:6},(_,i)=>`<span class="${i<step?'complete':''}"></span>`).join('');$('#goalAction').textContent=growth?'Show next step →':m===6?'Explore town upgrades →':'Show next step →';$('#contractsTab').hidden=!state.pier;$('#specialistPin').hidden=!state.pier;$('#specialistPin').dataset.select=state.specialisation&&state.specialists.includes(PATHS[state.specialisation].station)?PATHS[state.specialisation].station:'build';$('#specialistName').innerHTML=state.specialisation?PATHS[state.specialisation].building+'<small>'+(!state.specialists.includes(PATHS[state.specialisation].station)?'Investment available':underConstruction(state,PATHS[state.specialisation].station)?'Under construction':'Open production')+'</small>':'Specialist quarter<small>Choose your town direction</small>';
 $('#fieldLabel').textContent=state.ripe?'Ready to harvest':state.jobs.some(j=>j.key==='field')?'Growing':'Ready to plant';$('.ready-dot').hidden=!state.ripe;
 $('#millLabel').textContent=state.jobs.some(j=>j.key==='mill')?'Milling flour…':'Wheat → flour';$('#bakeryLabel').textContent=state.jobs.some(j=>j.key==='bakery')?'Baking bread…':'Flour → bread';
 $('#expName').innerHTML=has(state,'olive')?'Olive workshop<small>Open production</small>':'Olive workshop<small>Available to build</small>';
 $('#expIcon').textContent=has(state,'olive')?'❧':'＋';$('.expansion-pin').dataset.select=has(state,'olive')?'olive':'build';$('.expansion-pin').classList.toggle('empty',!has(state,'olive'));$('#newBuilding').hidden=!has(state,'olive')||!!underConstruction(state,'olive');
 $('#fishingName').innerHTML=has(state,'fishing')?'Fishing jetty<small>Open production</small>':'Fishing jetty<small>Available to build</small>';
 $('.fishing-pin').dataset.select=has(state,'fishing')?'fishing':'build';$('.fishing-pin').classList.toggle('empty',!has(state,'fishing'));$('#newJetty').hidden=!has(state,'fishing')||!!underConstruction(state,'fishing');$('#pierOverlay').hidden=!state.pier||!!underConstruction(state,'pier');
 for(const[type,id]of [['olive','expName'],['fishing','fishingName']]){const project=underConstruction(state,type);if(project)$('#'+id).innerHTML=(type==='olive'?'Olive workshop':'Fishing jetty')+'<small>Under construction</small>'; }
 $('#harbourLabel').textContent=state.pier?'3 routes available':!state.deliveries?'First delivery':'Coastal trade';
 $$('[data-speed]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.speed)===state.speed);b.setAttribute('aria-pressed',String(Number(b.dataset.speed)===state.speed));});
 $('#mapState').textContent=state.speed===0?'Paused':state.construction.length?'Crew on site · '+state.construction.length+' project'+(state.construction.length===1?'':'s'):state.jobs.length?state.jobs.length+' active / queued':'Tap a building · Swipe to explore';
 $('#autosaveWarning').hidden=storageOK;
 $('#pauseLabel').textContent=state.speed===0?'Paused — choose a speed to resume':'Simulation speed';
 updateGuide();checkMilestones();updateProgress();save();
}
function updateProgress(){const crop=state.jobs.find(j=>j.key==='field'),growth=state.ripe?1:crop?Math.max(0,1-crop.left/RECIPES.field.duration):0;$('#fieldSoil').style.opacity=String(1-Math.max(0,(growth-.3)/.7));$$('[data-stationtime]').forEach(el=>{const j=state.jobs.find(j=>RECIPES[j.key].station===el.dataset.stationtime);el.textContent=j?RECIPES[j.key].name+' · '+Math.ceil(j.left)+'s'+(state.speed===0?' · paused':' remaining'):'';});for(const p of state.construction){const text=$(`[data-buildtime="${p.type}"]`),bar=$(`[data-buildbar="${p.type}"]`);if(text)text.textContent=Math.ceil(p.left)+'s'+(state.speed===0?' · paused':' remaining');if(bar)bar.style.width=(1-p.left/CONSTRUCTION_SECONDS)*100+'%';}const seen=new Set();state.jobs.forEach((j,i)=>{const r=RECIPES[j.key],queued=seen.has(r.station);seen.add(r.station);const label=$(`[data-jobtime="${i}"]`),bar=$(`[data-jobbar="${i}"]`);if(label)label.textContent=queued?'Queued':Math.ceil(j.left)+'s'+(state.speed===0?' · paused':'');if(bar)bar.style.width=Math.max(0,(1-j.left/recipeDuration(state,j.key))*100)+'%';});}
function choose(t,s,scroll=false){tab=t;if(s)station=s;render();if(scroll&&matchMedia('(max-width:740px)').matches)$('.management').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
function goIngredient(item){const recipe=({fish:'fishing',oil:'press',olives:'olives',planks:'saw',boatparts:'fittings',grapes:'grapes',wine:'wine'})[item];if(recipe&&!unlocked(state,recipe)){choose('build',null,true);return;}if(['wood','stone'].includes(item)){selectOrder(state,'materials');choose('trade',null,true);return;}if(['planks','boatparts'].includes(item)){choose('produce','boatyard',true);return;}if(['grapes','wine'].includes(item)){choose('produce','estate',true);return;}if(item==='bread'){if(state.stock.flour>=2||state.jobs.some(j=>j.key==='bakery'))choose('produce','bakery',true);else goIngredient('flour');}else if(item==='flour'){if(state.stock.wheat>=2||state.jobs.some(j=>j.key==='mill'))choose('produce','mill',true);else choose('produce','field',true);}else choose('produce',({wheat:'field',olives:'olive',oil:'olive',fish:'fishing'})[item]||'field',true);}
function nextStep(){if(state.pier){choose(chapterTwo(state).target,null,true);return;}const m=milestone(state);if(m===0)choose('produce','field',true);else if(m===1)goIngredient('flour');else if(m===2)goIngredient('bread');else if(m===4||m===6)choose('build',null,true);else if(m===5&&state.deliveries>=2&&canAfford(state,PIER_COST))choose('build',null,true);else{const o=order(state),missing=Object.entries(o.cost).find(([k,v])=>state.stock[k]<v);if(missing)goIngredient(missing[0]);else choose('trade',null,true);}}
function showDialog(html){$('#dialogContent').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();}
function downloadSave(){const a=document.createElement('a'),blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);a.href=url;a.download='Little-Harbour-Save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save exported. Keep it to continue in a later version.');}
function settings(){showDialog(`<div class="panel-eyebrow">PLAYTEST 07</div><h2>Your harbour</h2><p>${storageOK?'Progress saves automatically in this browser.':'Browser storage is unavailable. Export your save before closing.'} Export a copy to move your town between devices or prototype versions.</p><div class="save-actions"><button class="button" data-action="export">Export town save</button><button class="button secondary" data-action="import">Import town save</button></div><p class="hint">The game pauses while this panel is open. Closing or hiding the page also pauses it.</p><button class="text-button reset-link" data-action="confirm-reset">Start a new town</button>`);}
function help(){showDialog('<div class="panel-eyebrow">WELCOME TO PORTO LUME</div><h2>A working harbour.</h2><p>Start with one field, a mill and a bakery. Turn your first harvest into four bread, trade it, then decide what your harbour becomes.</p><ol class="onboarding-steps"><li><strong>Harvest</strong><span>Collect wheat from the field.</span></li><li><strong>Produce</strong><span>Mill wheat into flour, then bake bread. Buildings work in parallel.</span></li><li><strong>Trade</strong><span>Deliver goods for coins and building materials.</span></li><li><strong>Expand</strong><span>Add fishing or olive oil. Extend the quay to unlock both and automate production.</span></li></ol><p>The card beneath the map suggests the next useful action and counts goods already in production. Production → Overview manages every workshop. Use Fill queue for several batches, or tap a resource to find its source. Harvest & replant starts the next crop in one tap.</p><p>Use pause, 1× or 3×. Nothing spoils and no delivery expires.</p><button class="button" data-action="begin">Start at the wheat field</button><p class="hint">Solo browser prototype. Shared multiplayer and a native iPhone app are not included in this build.</p>');}
function handleClick(e){const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.speed!==undefined){state.speed=Number(b.dataset.speed);render();return;}
 if(b.dataset.tab){choose(b.dataset.tab,b.dataset.tab==='produce'?'overview':null,true);return;}
 if(b.dataset.station){choose('produce',b.dataset.station,true);return;}
 if(b.dataset.select){const s=b.dataset.select;choose(s==='trade'?'trade':s==='build'?'build':'produce',!['trade','build'].includes(s)?s:null,true);return;}
 const a=b.dataset.action;let success=false;
 if(a==='begin'){state.onboarded=true;$('#dialog').close();choose('produce','field',true);return;}
 if(a==='watch-build'){focusMap(b.dataset.key);return;}
 if(a==='refit-options'){showDialog(refitCard(b.dataset.key));return;}
 if(a==='refit'){const st=b.dataset.key,mode=b.dataset.mode;if(state.refits[st]&&state.refits[st]!==mode){showDialog(`<div class="panel-eyebrow">CHANGE WORKSHOP SETUP</div><h2>Replace ${REFITS[st][state.refits[st]].name.toLowerCase()}?</h2><p>Install ${REFITS[st][mode].name.toLowerCase()} for ${costs(REFITS[st][mode].cost)}. Your current improvement is replaced without a refund. Other workshops keep their setups.</p><button class="button" data-action="confirm-refit" data-key="${st}" data-mode="${mode}">Pay & replace setup</button>`);return;}success=installRefit(state,st,mode);if(success){if($('#dialog').open)$('#dialog').close();toast(REFITS[st][mode].name+' installed.');}else{toast(refitBlocker(state,st,mode));return;}}
 if(a==='confirm-refit'){success=installRefit(state,b.dataset.key,b.dataset.mode);if(success){$('#dialog').close();toast('Workshop setup replaced.');}else{toast(refitBlocker(state,b.dataset.key,b.dataset.mode));return;}}
 if(a==='guide'){runGuide();return;}
 if(a==='dismiss-milestone'){$('#milestoneNotice').hidden=true;clearTimeout(milestoneTimer);return;}
 if(a==='milestone-next'){$('#milestoneNotice').hidden=true;clearTimeout(milestoneTimer);nextStep();return;}
 if(a==='map-view'){mapFitted=!mapFitted;render();return;}
 if(a==='map-labels'){labelsVisible=!labelsVisible;render();return;}
 if(a==='next'){nextStep();return;}
 if(a==='map'){$('#map').scrollIntoView({behavior:'smooth',block:'center'});return;}
 if(a==='ingredient'){goIngredient(b.dataset.key);return;}
 if(a==='missing'){const item=Object.entries(order(state).cost).find(([k,v])=>state.stock[k]<v);if(item)goIngredient(item[0]);return;}
 if(a==='open-trade'){choose('trade',null,true);return;}
 if(a==='batch'){const n=queueBatch(state,b.dataset.key,Number(b.dataset.count));success=n>0;if(success)toast(n+' batches queued · '+RECIPES[b.dataset.key].name.toLowerCase());}
 if(a==='harvest-replant'){success=harvestReplant(state);if(success){toast('Collected 6 wheat · next crop planted');scene?.emit('harvest');}}
 if(a==='harvest'){success=harvest(state);if(success){toast('Harvest collected · +6 wheat');scene?.emit('harvest');}}
 if(a==='start'){success=start(state,b.dataset.key);if(success)toast(RECIPES[b.dataset.key].name+' queued');}
 if(a==='cancel'){success=cancel(state,Number(b.dataset.index));if(success)toast('Queued batch cancelled. Ingredients returned.');}
 if(a==='prioritize'){success=prioritize(state,Number(b.dataset.index));if(!success)toast('That batch is already next for its workshop.');}
 if(a==='target'){success=setTarget(state,b.dataset.key,Number(b.dataset.value));if(success)toast(Number(b.dataset.value)?'Production will maintain the selected stock.':'Automatic production stopped. Existing batches remain queued.');}
 if(a==='route'){success=selectOrder(state,b.dataset.key);}
 if(a==='dispatch'){const destination=order(state).name;success=dispatch(state);if(success){toast(state.deliveries===1?'First delivery complete. Choose your expansion.':'Shipment delivered. Funds and materials received.');scene?.emit('shipment',destination);}}
 if(a==='go-build'){choose('build',null,true);return;}
 if(a==='build'){success=build(state,b.dataset.key);if(success){toast('Construction started. Your crew is on site.');station=b.dataset.key;tab='produce';}}
 if(a==='upgrade'){success=upgrade(state);if(success)toast('Quay extended. New routes and stock targets unlocked.');}
 if(a==='workshops'){success=upgradeWorkshops(state);if(success)toast('Four production slots are now available at each workshop.');}
 if(a==='specialise'){success=specialise(state,b.dataset.key);if(success){station=state.specialists.includes(PATHS[b.dataset.key].station)?PATHS[b.dataset.key].station:'field';toast('Town direction: '+PATHS[b.dataset.key].name);}else toast(pathBlocker(state,b.dataset.key));}
 if(a==='invest'){success=invest(state);if(success){station=PATHS[state.specialisation].station;tab='produce';toast('Your specialist crew is building '+PATHS[state.specialisation].building.toLowerCase()+'.');}}
 if(a==='accept-contract'){success=acceptContract(state,b.dataset.key);if(success)toast('Contract accepted. Prepare the first shipment.');}
 if(a==='contract-missing'){const missing=state.contract&&Object.entries(CONTRACTS[state.contract.id].cost).find(([k,v])=>state.stock[k]<v);if(missing)goIngredient(missing[0]);return;}
 if(a==='contract-dispatch'){success=dispatchContract(state);if(success){scene?.emit('shipment');toast(state.contract?'Contract shipment delivered.':'Contract complete · bonus earned and partnership established.');}}
 if(a==='leave-contract'){showDialog('<div class="panel-eyebrow">RELEASE CONTRACT</div><h2>Leave this contract?</h2><p>Unshipped goods stay in your storehouse. Already delivered shipments remain delivered and are not refunded. You can accept another contract afterwards.</p><button class="button" data-action="confirm-leave">Release contract</button>');return;}
 if(a==='confirm-leave'){success=abandonContract(state);$('#dialog').close();if(success)toast('Contract released. Your remaining goods are available.');}
 if(a==='charter'){success=establishCharter(state);if(success)toast('Harbour charter earned. Both specialist plots unlocked.');}
 if(a==='go-contracts'){choose('contracts',null,true);return;}
 if(a==='export'){downloadSave();return;}
 if(a==='import'){$('#importSave').click();return;}
 if(a==='apply-import'&&pendingImport){state=pendingImport;scene?.reset();resetMilestones();pendingImport=null;tab='produce';station='field';$('#dialog').close();success=true;toast('Town imported successfully.');}
 if(a==='reset'){state=fresh();scene?.reset();resetMilestones();state.onboarded=true;tab='produce';station='field';$('#dialog').close();success=true;toast('A new harbour is ready.');}
 if(a==='confirm-reset'){showDialog('<div class="panel-eyebrow">START AGAIN</div><h2>Start a new town?</h2><p>This replaces the saved town in this browser. Export your current town first if you want to keep it.</p><button class="button secondary" data-action="export">Export current town</button><button class="button" data-action="reset">Start a new town</button>');return;}
 if(success)render();else if(a&&!['prioritize'].includes(a))toast('That action is not available yet.');
}
function init(){
 scene=createHarbourScene($('#activityCanvas'),()=>state,()=>document.hidden||$('#dialog').open,recipeDuration);
 resetMilestones();
 document.addEventListener('click',handleClick);$('#help').onclick=help;$('#settings').onclick=settings;
 $('#closeDialog').onclick=()=>{state.onboarded=true;pendingImport=null;$('#dialog').close();save();};
 $('#dialog').addEventListener('cancel',()=>{state.onboarded=true;pendingImport=null;save();});
 $('#importSave').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>100000)throw Error('Choose a Little Harbour JSON save under 100 KB.');pendingImport=parseSave(await file.text());showDialog(`<div class="panel-eyebrow">IMPORT TOWN</div><h2>Replace this town?</h2><p>The imported town has ${pendingImport.deliveries} deliveries, ${pendingImport.coins} coins and ${pendingImport.businesses.length} new businesses.</p><p>It will replace the current town in this browser.</p><button class="button secondary" data-action="export">Export current town first</button><button class="button" data-action="apply-import">Import this town</button>`);}catch(error){pendingImport=null;toast(error.message||'That save could not be imported.');}});
 let last=performance.now(),saveClock=0;
 setInterval(()=>{const now=performance.now(),dt=Math.min((now-last)/1000,.5);last=now;if(document.hidden||$('#dialog').open)return;const before=state.jobs.length,stock=JSON.stringify(state.stock),wheat=state.stock.wheat,completed=tick(state,dt,e=>scene?.emit('produced',Object.keys(RECIPES[e.key].output)[0]));if(state.stock.wheat>wheat)scene?.emit('harvest');if(completed||before!==state.jobs.length||stock!==JSON.stringify(state.stock))render();else updateProgress();saveClock+=dt;if(saveClock>3){save();saveClock=0;}},200);
 document.addEventListener('visibilitychange',()=>{last=performance.now();save();});window.addEventListener('pagehide',save);
 render();if(saveWarning)toast(saveWarning);if(!state.onboarded)help();
}
init();
